/*------------------------------------------------------------------------------------------------------------------------------------------------------------------------AUTOR: ROBERTO RECIFEDATA : 17/07/2023DESCRICAO: CONTAS A RECEBER------------------------------------------------------------------------------------------------------------------------------------------------------------------------SP_CONTAS_A_RECEBER '01/01/2025','31/12/2025','01/01/2023','31/12/2025',3------------------------------------------------------------------------------------------------------------------------------------------------------------------------DROP PROCEDURE SP_CONTAS_A_RECEBER------------------------------------------------------------------------------------------------------------------------------------------------------------------------*/CREATE PROCEDURE [dbo].[SP_CONTAS_A_RECEBER](	@MV_PAR01		VARCHAR(10),	@MV_PAR02		VARCHAR(10),	@MV_PAR03		VARCHAR(10),	@MV_PAR04		VARCHAR(10),	@MV_PAR05		FLOAT)			--1-Abertos 2-Recebidos 3-TodosAS------------------------------------------------------------------------------------------------------------------------------------------------------------------------SELECT @MV_PAR01=SUBSTRING(@MV_PAR01,7,4)+SUBSTRING(@MV_PAR01,4,2)+SUBSTRING(@MV_PAR01,1,2)SELECT @MV_PAR02=SUBSTRING(@MV_PAR02,7,4)+SUBSTRING(@MV_PAR02,4,2)+SUBSTRING(@MV_PAR02,1,2)SELECT @MV_PAR03=SUBSTRING(@MV_PAR03,7,4)+SUBSTRING(@MV_PAR03,4,2)+SUBSTRING(@MV_PAR03,1,2)SELECT @MV_PAR04=SUBSTRING(@MV_PAR04,7,4)+SUBSTRING(@MV_PAR04,4,2)+SUBSTRING(@MV_PAR04,1,2)------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT ON ------------------------------------------------------------------------------------------------------------------------------------------------------------------------SELECT	E1_FILIAL FILIAL,		CONVERT(VARCHAR(10),CONVERT(DATETIME,E1_EMISSAO),103) AS 'EMISSAO',		E1_NUM 'NOTA FISCAL',		E1_PREFIXO PREFIXO,		E1_TIPO TIPO,		E1_PARCELA 'PARC.',		E1_PEDIDO AS 'PEDIDO',		'FORNECEDOR/CLIENTE'=(SELECT A1_NOME FROM SA1010 WHERE A1_FILIAL='' AND A1_COD+A1_LOJA=E1_CLIENTE+E1_LOJA AND D_E_L_E_T_<>'*'),		CONVERT(VARCHAR(10),CONVERT(DATETIME,E1_VENCREA),103) VENCIMENTO,		E1_VALOR VALOR,		E1_SALDO SALDO,		E1_HIST HISTORICO,		E1_NATUREZ NATUREZA,		'DESCRICAO'=(SELECT ED_DESCRIC FROM SED010 WHERE ED_FILIAL='' AND E1_NATUREZ=ED_CODIGO AND D_E_L_E_T_<>'*'),		E1_PORTADO AS 'BANCO'FROM	SE1010WHERE	E1_VENCREA BETWEEN @MV_PAR01 AND @MV_PAR02		AND E1_EMISSAO BETWEEN @MV_PAR03 AND @MV_PAR04		AND (@MV_PAR05=1 AND E1_SALDO>0 OR @MV_PAR05=2 AND E1_SALDO=0 OR @MV_PAR05=3)		AND D_E_L_E_T_<>'*'ORDER BY E1_VENCREA,E1_NUM,E1_PREFIXO,E1_PARCELA------------------------------------------------------------------------------------------------------------------------------------------------------------------------SET NOCOUNT OFF------------------------------------------------------------------------------------------------------------------------------------------------------------------------